use roles_rust_case::is_allowed;
use std::fs;

#[test]
fn test_is_allowed() {
    let data = fs::read_to_string("allowed_roles.txt").unwrap();
    for role in data.trim().split(',') {
        assert!(is_allowed(role.trim()), "is_allowed({}) should be true", role);
    }
    assert!(!is_allowed("not_a_real_role"), "is_allowed should reject an unknown role");
}

